#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <memory>
#include <numeric>
#include <random>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock; static constexpr uint64_t SEED=0xB0D2A020ULL;
static inline uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);} static inline uint64_t fnv1a(const std::string&s,uint64_t h=1469598103934665603ULL){for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct A{uint32_t rho;uint64_t fp;};static inline A enc(const std::string&k,uint32_t M){uint64_t h0=mix64(fnv1a(k)),h1=mix64(h0^0xD6E8FEB86659FD93ULL),h2=mix64(h1^0xA5A35625D3E7E5B9ULL),h3=mix64(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0&(M-1)),mix64(h0^(h1<<1)^(h2>>1)^h3)};}
static uint32_t pow2ceil(uint64_t x){uint64_t p=1;while(p<x)p<<=1;return uint32_t(p);}
struct Slot{uint64_t key=0,val=0;uint32_t dist=0;bool used=false;};
class RH{std::vector<Slot>s;size_t mask;public:RH(size_t n=1,double max_load=.78){size_t c=8;while(double(c)*max_load<double(std::max<size_t>(1,n)))c<<=1;s.resize(c);mask=c-1;}void put(uint64_t k,uint64_t v){size_t i=mix64(k)&mask;Slot cur{k,v,0,true};for(;;){auto&x=s[i];if(!x.used){x=cur;return;}if(x.key==k){x.val=v;return;}if(x.dist<cur.dist)std::swap(x,cur);i=(i+1)&mask;++cur.dist;}}bool get(uint64_t k,uint64_t&v)const{size_t i=mix64(k)&mask;uint32_t d=0;for(;;){const auto&x=s[i];if(!x.used||x.dist<d)return false;if(x.key==k){v=x.val;return true;}i=(i+1)&mask;++d;}}size_t bytes()const{return s.capacity()*sizeof(Slot);}};
class Compact{std::vector<std::pair<uint64_t,uint64_t>>a;public:explicit Compact(size_t n=0){a.reserve(n);}void put(uint64_t k,uint64_t v){a.emplace_back(k,v);}void finish(){std::sort(a.begin(),a.end());}bool get(uint64_t k,uint64_t&v)const{auto it=std::lower_bound(a.begin(),a.end(),std::pair<uint64_t,uint64_t>{k,0},[](auto&x,auto&y){return x.first<y.first;});if(it==a.end()||it->first!=k)return false;v=it->second;return true;}size_t bytes()const{return a.capacity()*sizeof(a[0]);}};
struct Part{std::unique_ptr<Compact>c;std::unique_ptr<RH>r;};
class LocalDB{uint32_t M;std::vector<Part>p;public:LocalDB(uint32_t m,const std::vector<A>&as,size_t compact_limit=16):M(m),p(m){std::vector<size_t>cnt(M);for(auto&a:as)cnt[a.rho]++;for(uint32_t i=0;i<M;++i)if(cnt[i]){if(cnt[i]<=compact_limit)p[i].c=std::make_unique<Compact>(cnt[i]);else p[i].r=std::make_unique<RH>(cnt[i]);}}void put(const A&a,uint64_t v){auto&x=p[a.rho];if(x.c)x.c->put(a.fp,v);else x.r->put(a.fp,v);}void finish(){for(auto&x:p)if(x.c)x.c->finish();}bool get(const std::string&k,uint64_t&v)const{auto a=enc(k,M);auto&x=p[a.rho];return x.c?x.c->get(a.fp,v):x.r&&x.r->get(a.fp,v);}size_t bytes()const{size_t b=p.capacity()*sizeof(Part);for(auto&x:p){if(x.c)b+=x.c->bytes();if(x.r)b+=x.r->bytes();}return b;}void stats(size_t&cp,size_t&rp)const{cp=rp=0;for(auto&x:p){cp+=bool(x.c);rp+=bool(x.r);}}};
struct Stat{double mean,p50,p95,p99,tput;};template<class F>Stat bench(F&&f,const std::vector<std::string>&ks,const std::vector<size_t>&q){std::vector<double>l;l.reserve(q.size());volatile uint64_t sink=0;auto A0=Clock::now();for(auto i:q){auto a=Clock::now();uint64_t v=0;f(ks[i],v);auto b=Clock::now();sink^=v;l.push_back(std::chrono::duration<double,std::micro>(b-a).count());}auto B=Clock::now();std::sort(l.begin(),l.end());auto at=[&](double p){return l[size_t(p*(l.size()-1))];};return{std::accumulate(l.begin(),l.end(),0.0)/l.size(),at(.5),at(.95),at(.99),q.size()/std::chrono::duration<double>(B-A0).count()};}
static std::vector<std::string> keys(const std::string&w,size_t N,uint32_t M){std::vector<std::string>o;o.reserve(N);if(w=="hotrho"){uint32_t hot=std::max(1u,M/32);uint64_t c=0;while(o.size()<N){auto k="H_"+std::to_string(c++);if(enc(k,M).rho<hot)o.push_back(k);}}else if(w=="prefix"){for(size_t i=0;i<N;++i)o.push_back("TENANT_SHARED_PREFIX_RECORD_"+std::to_string(i));}else for(size_t i=0;i<N;++i)o.push_back("K_"+std::to_string(i));return o;}
int main(int argc,char**argv){size_t N=argc>1?std::stoull(argv[1]):100000,Q=50000;std::cout<<"workload,target_density,rho_partitions,engine,mean_us,p50_us,p95_us,p99_us,throughput_ops_s,bytes_per_record,compact_parts,robin_parts\n";for(size_t target:{16ul,32ul,64ul,128ul,256ul}){uint32_t M=pow2ceil(std::max<uint64_t>(64,(N+target-1)/target));for(std::string w:{"sequential","prefix","hotrho"}){auto ks=keys(w,N,M);std::vector<A>as;as.reserve(N);for(auto&k:ks)as.push_back(enc(k,M));std::mt19937_64 rng(SEED);std::uniform_int_distribution<size_t>d(0,N-1);std::vector<size_t>q(Q);for(auto&x:q)x=d(rng);LocalDB db(M,as,16);for(size_t i=0;i<N;++i)db.put(as[i],i);db.finish();size_t c,r;db.stats(c,r);auto s=bench([&](auto&k,uint64_t&v){return db.get(k,v);},ks,q);std::cout<<w<<','<<target<<','<<M<<",rho_compact_robin,"<<s.mean<<','<<s.p50<<','<<s.p95<<','<<s.p99<<','<<s.tput<<','<<double(db.bytes())/N<<','<<c<<','<<r<<'\n';}}
// matched global Robin Hood baseline at M=1 only for timing/memory reference
uint32_t M=1;auto ks=keys("sequential",N,M);std::vector<A>as;as.reserve(N);for(auto&k:ks)as.push_back(enc(k,M));RH g(N);for(size_t i=0;i<N;++i)g.put(as[i].fp,i);std::mt19937_64 rng(SEED);std::uniform_int_distribution<size_t>d(0,N-1);std::vector<size_t>q(Q);for(auto&x:q)x=d(rng);auto s=bench([&](auto&k,uint64_t&v){return g.get(enc(k,1).fp,v);},ks,q);std::cout<<"sequential,0,1,global_robin_hood,"<<s.mean<<','<<s.p50<<','<<s.p95<<','<<s.p99<<','<<s.tput<<','<<double(g.bytes())/N<<",0,1\n";
}
